// WishServiceClient is a client for the plan.v1.WishService service.
type WishServiceClient interface {
	// Make a wish.
	Make(context.Context, *connect.Request[v1.WishServiceMakeRequest]) (*connect.Response[v1.WishServiceMakeResponse], error)
	// List the wishes: the active ones by rank, the first has priority; then the paused ones and the granted ones,
	// each in its own order (djinn wish reorder), the one paused or granted last first.
	List(context.Context, *connect.Request[v1.WishServiceListRequest]) (*connect.Response[v1.WishServiceListResponse], error)
	// Export a wish to a file, to open it on another machine: its plan, questions, decisions, blocks and journal.
	// Never code, which travels through Git, never a secret, never a local path: projects are named by their name
	// and remote.
	Export(context.Context, *connect.Request[v1.WishServiceExportRequest]) (*connect.Response[v1.WishServiceExportResponse], error)
	// Import a wish from a file written by export. Each project is found on this machine by its remote, then by
	// its name; one not found is added without a folder, for djinn project add <folder> to attach.
	Import(context.Context, *connect.Request[v1.WishServiceImportRequest]) (*connect.Response[v1.WishServiceImportResponse], error)
	// Import a wish from the content of a file, as the window reads it. The journal records every import this
	// way, with the content, whatever way it came.
	ImportData(context.Context, *connect.Request[v1.WishServiceImportDataRequest]) (*connect.Response[v1.WishServiceImportDataResponse], error)
	// Describe a wish: a few lines that say what it is for, its scope and where it goes, in place of what it had.
	// Empty text takes it back to the title.
	Describe(context.Context, *connect.Request[v1.WishServiceDescribeRequest]) (*connect.Response[v1.WishServiceDescribeResponse], error)
	// Rename a wish: what you wish, in a sentence, in place of what it had.
	Rename(context.Context, *connect.Request[v1.WishServiceRenameRequest]) (*connect.Response[v1.WishServiceRenameResponse], error)
	// Set a wish's icon in the window's menu, in place of what it had: a name of the bank (djinn wish icons) that says
	// its subject. An empty name takes it back to its mark.
	Icon(context.Context, *connect.Request[v1.WishServiceIconRequest]) (*connect.Response[v1.WishServiceIconResponse], error)
	// List the bank of wish icons a wish's icon is chosen from, family by family: each name with its words in English
	// and in French. --search keeps the icons whose name, family or words hold every word given, in either language.
	Icons(context.Context, *connect.Request[v1.WishServiceIconsRequest]) (*connect.Response[v1.WishServiceIconsResponse], error)
	// Add a project to a wish, by its name or identifier: the wish then works in it as in the projects it was made
	// with. Its tasks may spawn there, and its finished work goes to the branch the project's checkout is on, as when a
	// wish is made. A project already in the wish, or unknown, is refused. Removing a project is not possible.
	AddProject(context.Context, *connect.Request[v1.WishServiceAddProjectRequest]) (*connect.Response[v1.WishServiceAddProjectResponse], error)
	// The brief of a wish: where it stands, enough for any agent to lead it from there, written by Djinn from the
	// store, no model. Every lead starts by reading it. First the wish (its description, its azimas, its tasks
	// running and waiting, its open questions, its latest decisions and blocks, the last lead and when it last
	// acted), then how to lead it (Djinn's rules, the rules of its projects). No local path, no secret.
	Brief(context.Context, *connect.Request[v1.WishServiceBriefRequest]) (*connect.Response[v1.WishServiceBriefResponse], error)
	// Everything a wish holds, as an export carries it, and its projects on this machine, for the window.
	Snapshot(context.Context, *connect.Request[v1.WishServiceSnapshotRequest]) (*connect.Response[v1.WishServiceSnapshotResponse], error)
	// Allow the wish's workers a right in one of its projects, for every task to come: edit, or auto (edit in their
	// agent's auto mode); none takes it back. It weighs over the project's configuration, for this wish only.
	Allow(context.Context, *connect.Request[v1.WishServiceAllowRequest]) (*connect.Response[v1.WishServiceAllowResponse], error)
	// Set where the wish's finished work is committed, and when it is pushed: the integration branch of one of its
	// projects, how long and how many tasks committed a push waits for when no azima ends, and whether Djinn pushes by
	// itself or asks first. Only what is given changes. The branch is refused while a merge runs into the wish's branch
	// in that project: its work, a correction or a review, or main's merge.
	SetIntegration(context.Context, *connect.Request[v1.WishServiceSetIntegrationRequest]) (*connect.Response[v1.WishServiceSetIntegrationResponse], error)
	// Show or change the push strategy of a wish: wish (one branch per wish) or azima (one branch per azima).
	PushStrategy(context.Context, *connect.Request[v1.WishServicePushStrategyRequest]) (*connect.Response[v1.WishServicePushStrategyResponse], error)
	// Show or change whether a wish is the principal wish. When set, this wish's lead is the principal lead; when unset,
	// the active wish with the lowest rank is principal.
	Principal(context.Context, *connect.Request[v1.WishServicePrincipalRequest]) (*connect.Response[v1.WishServicePrincipalResponse], error)
	// Grant a wish: you say it is done. Djinn never grants a wish itself; it proposes it once the wish is ready (every
	// task finished, no question open), and you may grant it before.
	Grant(context.Context, *connect.Request[v1.WishServiceGrantRequest]) (*connect.Response[v1.WishServiceGrantResponse], error)
	// Pause a wish: it keeps everything, its workers stop and wait to resume with it, and it leaves its place among the
	// three active wishes to another one.
	Pause(context.Context, *connect.Request[v1.WishServicePauseRequest]) (*connect.Response[v1.WishServicePauseResponse], error)
	// Make a paused or granted wish active again, last by rank; its stopped workers start again. Three wishes are
	// active at most: when three are, it takes the third place, and the third wish is paused.
	Activate(context.Context, *connect.Request[v1.WishServiceActivateRequest]) (*connect.Response[v1.WishServiceActivateResponse], error)
	// Delete a wish, and all that belongs to it: its tasks and their events, its questions, its blocks. Its workers
	// stop first. A task's worktree goes when it holds no work: clean, and no commit
	// beyond the project's current branch; the others stay, said with why. Branches all stay. It cannot be undone.
	Delete(context.Context, *connect.Request[v1.WishServiceDeleteRequest]) (*connect.Response[v1.WishServiceDeleteResponse], error)
	// Move a wish to another rank: --to 1 gives it priority over the others. A wish that is not active becomes active
	// there, the third place at most, and the wish it pushes past the third place is paused.
	Move(context.Context, *connect.Request[v1.WishServiceMoveRequest]) (*connect.Response[v1.WishServiceMoveResponse], error)
	// Move a paused or granted wish to another place in the list of the wishes of its state: --to 1 puts it first. It
	// stays paused or granted: djinn wish move makes it active.
	Reorder(context.Context, *connect.Request[v1.WishServiceReorderRequest]) (*connect.Response[v1.WishServiceReorderResponse], error)
	// Render the wish's page to a file: one HTML page standing alone, with its open questions first, then what waits
	// for you, its tasks, its decisions, its blocks and its journal. Djinn writes it, no model does. No secret, no
	// local path.
	Render(context.Context, *connect.Request[v1.WishServiceRenderRequest]) (*connect.Response[v1.WishServiceRenderResponse], error)
	// Render the wish's page in Djinn's data folder, print where, and keep it up to date while djinn up runs: every
	// change of the wish renders it again, at most once a second. Publishing it stays yours: share the file, or
	// republish it where you put it last time. Delete the file to stop.
	Sync(context.Context, *connect.Request[v1.WishServiceSyncRequest]) (*connect.Response[v1.WishServiceSyncResponse], error)
	// Find the wish a request belongs to, without a model. Djinn ranks the wishes by the words of their titles, the
	// projects the request names or links to (a GitLab or GitHub link whose repository is a project's remote), and
	// their latest blocks. It proposes to file the request in the closest ones, or to open a new wish with a title
	// and a project. A request that matches the wish template of a skill in those projects (metadata.djinn.wish in
	// its SKILL.md) proposes the template's wish: its title, its watcher, the skill for the lead to follow. With
	// --ask, the proposal is a question on the wish --wish-id: answering it files the request, or makes the new wish,
	// starts its watcher and opens it in the window; the lead is told where the request went.
	Route(context.Context, *connect.Request[v1.WishServiceRouteRequest]) (*connect.Response[v1.WishServiceRouteResponse], error)
	// Follow what changes, as it changes: which wish, and what in it. The first message names everything, to read; then
	// each change follows, with the tasks, questions and blocks that changed, whole, so that a reader replaces them
	// without reading the others again; changes close together come as one. A task's events come from
	// TaskService.Watch.
	Watch(context.Context, *connect.Request[v1.WishServiceWatchRequest]) (*connect.ServerStreamForClient[v1.WishServiceWatchResponse], error)
}

